<?php require __DIR__.'/includes/bootstrap.php';require_permission('settings.manage');$pageTitle='API Settings';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$endpoint=trim($_POST['endpoint']??'');if(!filter_var($endpoint,FILTER_VALIDATE_URL)||!in_array(parse_url($endpoint,PHP_URL_SCHEME),['https','http'],true))throw new RuntimeException('Enter a valid HTTP(S) endpoint.');$username=trim($_POST['username']??'');$password=(string)($_POST['password']??'');if($username==='')throw new RuntimeException('API username is required.');save_setting('sticky_endpoint',$endpoint);save_setting('sticky_username',$username);if($password!=='')save_setting('sticky_password_enc',encrypt_secret($password));foreach(['main_product_ids','upsell_product_ids','subscription_product_ids'] as $k){$raw=trim($_POST[$k]??'');if($raw!==''&&!preg_match('/^[0-9,\s]+$/',$raw))throw new RuntimeException('Product IDs must be comma-separated numeric IDs.');save_setting($k,normalize_ids($raw));}flash('success','API settings saved. Credentials are encrypted at rest.');audit('api_settings_updated');redirect('settings.php');}catch(Throwable $e){$error=$e->getMessage();}}$pageTitle='API Settings';require __DIR__.'/includes/header.php';?><h1>API Settings</h1><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><section class="panel"><p>API requests are sent server-side using HTTP POST, Basic authentication, and JSON. Leave password blank to keep the stored password.</p><form method="post"><?=csrf_field()?><div class="field"><label>API endpoint</label><input type="url" name="endpoint" value="<?=e(setting('sticky_endpoint','https://wellingtonfinancial1.sticky.io/api/v1/order_find'))?>" required></div><div class="field"><label>API username</label><input name="username" value="<?=e(setting('sticky_username',''))?>" required></div><div class="field"><label>API password</label><input type="password" name="password" autocomplete="new-password"><span class="help">Stored encrypted. Never place production credentials in source control.</span></div><?php foreach(['main_product_ids'=>'Main product IDs','upsell_product_ids'=>'Upsell product IDs','subscription_product_ids'=>'Subscription product IDs'] as $k=>$label):?><div class="field"><label><?=e($label)?></label><input name="<?=e($k)?>" value="<?=e(setting($k,''))?>" placeholder="382,151,12"><span class="help">Comma-separated numeric IDs. Saved without spaces and sorted descending numerically.</span></div><?php endforeach;?><button>Save settings</button></form></section><?php require __DIR__.'/includes/footer.php'; ?>